
-- NorthStar Health Group demo database (SQLite). Sales + Health Care + Insurance + HR in one story.



-- Tables shared by more than one business scope stay in 
CREATE TABLE Locations (Id INTEGER PRIMARY KEY, Name VARCHAR(1024) NOT NULL, City VARCHAR(1024) NOT NULL, State VARCHAR(1024) NOT NULL);
CREATE TABLE Users (
    Id INTEGER PRIMARY KEY, FirstName VARCHAR(1024) NOT NULL, LastName VARCHAR(1024) NOT NULL, BirthDate DATE NOT NULL,
    Gender VARCHAR(1024) NOT NULL, City VARCHAR(1024) NOT NULL, State VARCHAR(1024) NOT NULL);

-- HR
CREATE TABLE Departments (Id INTEGER PRIMARY KEY, Name VARCHAR(1024) NOT NULL);
CREATE TABLE Employees (
    Id INTEGER PRIMARY KEY, FirstName VARCHAR(1024) NOT NULL, LastName VARCHAR(1024) NOT NULL,
    DepartmentId INTEGER NOT NULL, LocationId INTEGER NOT NULL, ManagerId INTEGER,
    JobTitle VARCHAR(1024) NOT NULL, HireDate DATE NOT NULL, Salary DOUBLE PRECISION NOT NULL, EmploymentType VARCHAR(1024) NOT NULL);
CREATE TABLE PerformanceReviews (
    Id INTEGER PRIMARY KEY, EmployeeId INTEGER NOT NULL, ReviewYear INTEGER NOT NULL,
    Rating INTEGER NOT NULL, BonusAmount DOUBLE PRECISION NOT NULL);
CREATE TABLE LeaveRequests (
    Id INTEGER PRIMARY KEY, EmployeeId INTEGER NOT NULL, LeaveType VARCHAR(1024) NOT NULL,
    StartDate DATE NOT NULL, Days INTEGER NOT NULL, Status VARCHAR(1024) NOT NULL);

-- Sales
CREATE TABLE Products (
    Id INTEGER PRIMARY KEY, Name VARCHAR(1024) NOT NULL, Category VARCHAR(1024) NOT NULL,
    UnitPrice DOUBLE PRECISION NOT NULL, CostPrice DOUBLE PRECISION NOT NULL);
CREATE TABLE Orders (
    Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL, SalesRepId INTEGER NOT NULL, OrderDate DATE NOT NULL,
    Channel VARCHAR(1024) NOT NULL, Status VARCHAR(1024) NOT NULL);
CREATE TABLE OrderItems (
    Id INTEGER PRIMARY KEY, OrderId INTEGER NOT NULL, ProductId INTEGER NOT NULL,
    Quantity INTEGER NOT NULL, UnitPrice DOUBLE PRECISION NOT NULL, DiscountAmount DOUBLE PRECISION NOT NULL);

-- Health care
CREATE TABLE Diagnoses (
    Id INTEGER PRIMARY KEY, Code VARCHAR(1024) NOT NULL, Name VARCHAR(1024) NOT NULL, Category VARCHAR(1024) NOT NULL, IsChronic INTEGER NOT NULL);
CREATE TABLE Visits (
    Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL, DoctorId INTEGER NOT NULL, LocationId INTEGER NOT NULL,
    VisitDate DATE NOT NULL, VisitType VARCHAR(1024) NOT NULL, DiagnosisId INTEGER NOT NULL,
    DurationMinutes INTEGER NOT NULL, Charge DOUBLE PRECISION NOT NULL, Status VARCHAR(1024) NOT NULL);
CREATE TABLE LabResults (
    Id INTEGER PRIMARY KEY, VisitId INTEGER NOT NULL, TestName VARCHAR(1024) NOT NULL,
    ResultValue DOUBLE PRECISION NOT NULL, ReferenceMax DOUBLE PRECISION NOT NULL, IsAbnormal INTEGER NOT NULL);

-- Insurance
CREATE TABLE InsurancePlans (
    Id INTEGER PRIMARY KEY, Name VARCHAR(1024) NOT NULL, Tier VARCHAR(1024) NOT NULL, MonthlyPremium DOUBLE PRECISION NOT NULL,
    Deductible DOUBLE PRECISION NOT NULL, OutOfPocketMax DOUBLE PRECISION NOT NULL, CoinsuranceRate DOUBLE PRECISION NOT NULL);
CREATE TABLE Policies (
    Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL, PlanId INTEGER NOT NULL, AgentId INTEGER NOT NULL,
    StartDate DATE NOT NULL, EndDate VARCHAR(1024), Status VARCHAR(1024) NOT NULL);
CREATE TABLE PremiumPayments (
    Id INTEGER PRIMARY KEY, PolicyId INTEGER NOT NULL, PaymentDate DATE NOT NULL, Amount DOUBLE PRECISION NOT NULL, Status VARCHAR(1024) NOT NULL);
CREATE TABLE Claims (
    Id INTEGER PRIMARY KEY, PolicyId INTEGER NOT NULL, VisitId INTEGER NOT NULL, ClaimDate DATE NOT NULL,
    BilledAmount DOUBLE PRECISION NOT NULL, AllowedAmount DOUBLE PRECISION NOT NULL, PaidAmount DOUBLE PRECISION NOT NULL,
    Status VARCHAR(1024) NOT NULL, DenialReason VARCHAR(1024), ProcessedDate DATE);

-- SQLite cannot declare foreign keys across attached schemas. Keep those
-- logical relationships here so schema discovery can return both schema keys.
CREATE INDEX "IX_Visits_UserId" ON Visits (UserId);
CREATE INDEX "IX_Claims_PolicyId" ON Claims (PolicyId);
CREATE INDEX "IX_OrderItems_OrderId" ON OrderItems (OrderId);
CREATE INDEX "IX_Orders_UserId" ON Orders (UserId);



















